{

"kind": "propose",
"summary": "The container's CPU limit is insufficient, causing throttling and readiness probe failures. Increasing the CPU limit to 750m should alleviate the throttling and resolve the readiness issues.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "CPU limit is too low, causing throttling and readiness probe failures.",
    "supporting": ["ev-container_cpu", "ev-container_logs_tail", "ev-target_events"],
    "contradicting": ["cpu_throttled_at_limit"],
    "missing": ["node_cpu_contention"],
    "status": "open"
  },
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "The new version may use more CPU than the previous one, leading to throttling.",
    "supporting": ["ev-revision_health", "ev-rollout_history"],
    "contradicting": [],
    "missing": ["throttling_came_with_rollout"],
    "status": "open"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search", "uid": "uid-deployment-search"},
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raises the CPU limit for the 'api' container to 750m, reducing throttling and improving readiness probe success rates.",
  "rationale": "The container logs show high CPU throttling (81% of periods) despite a 500m limit. Increasing the limit to 750m (1.5x current) should clear the throttling and allow the application to meet readiness probe requirements without affecting memory or other resources.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-container_logs_tail", "ev-target_events", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "throttling_came_with_rollout"]
}
}
